#include <Arduino.h>
#include <time.h>

#include <yat/canvas.h>

// ---------------- which model this build is for ----------------
//
// platformio.ini defines exactly one YAT_MODEL_*, alongside the Seeed_GFX
// BOARD_SCREEN_COMBO that picks the matching panel driver. Everything else
// this firmware needs to know about the model is derived here, once, so a
// third model is a block in this section rather than a new #ifdef in every
// file that cares:
//
//   YAT_MODEL_NAME   the wire name — OTA asset filename, /api/status "model",
//                    serial STATUS "model". Must match .github/workflows/
//                    release.yml's matrix entry, which is what publishes
//                    firmware-<model>.bin.
//   kPanelProfile    the engine's DeviceProfile (canvas.h) every render()
//                    call site passes, so role- and literal-named inks are
//                    clamped to what this panel can actually show.
//   PANEL_REFRESH_S  how long a full refresh takes, for the one place we make
//                    a claim about it to somebody waiting (see below).
//
// The two models share the carrier board — identical pins, identical 800x480
// geometry — and differ only in the panel: E1002 is Spectra 6 (ED2208, 4bpp,
// six inks), E1001 is mono (UC8179, 1bpp, black/white).
#if defined(YAT_MODEL_E1001)
#define YAT_MODEL_NAME "e1001"
inline constexpr const yat::DeviceProfile& kPanelProfile = yat::kProfileE1001;
#elif defined(YAT_MODEL_E1002)
#define YAT_MODEL_NAME "e1002"
inline constexpr const yat::DeviceProfile& kPanelProfile = yat::kProfileE1002;
#else
#error "No YAT_MODEL_* defined — build through platformio.ini's e1001/e1002 env"
#endif

static constexpr const char* MODEL_NAME = YAT_MODEL_NAME;

// The macro and the profile are two spellings of the same fact, and the OTA
// asset name is built from the macro while /api/status reports the profile's
// own field — so make them impossible to disagree.
constexpr bool modelNamesAgree(const char* a, const char* b) {
  while (*a && *a == *b) {
    a++;
    b++;
  }
  return *a == *b;
}
static_assert(modelNamesAgree(YAT_MODEL_NAME, kPanelProfile.name),
              "YAT_MODEL_NAME and the engine DeviceProfile disagree about this model's name");

// An UPPER BOUND on how long the panel blocks for a full refresh, in seconds —
// the number the setup portal hands a phone so its progress copy can count
// down (see yat_portal.cpp's apply reply). A ceiling rather than a typical
// value on purpose: every consumer of it is somebody being asked to wait, and
// the only way to be wrong that breaks anything is to be under.
//
// E1002: ~30 s measured on the hardware, so 35 with a margin.
//
// E1001: NOT YET MEASURED. Mono panels are usually much faster than an E6,
// but the UC8179's real full-refresh time on this board is a hardware fact
// nobody here has observed, and guessing LOW is the one direction that
// breaks something — the portal would tell the household setup finished while
// the panel is still mid-refresh. So it starts at the E1002's number, which is
// only ever too generous, and the honest fix is one measurement.
// TODO(hardware): time epaper.update() on an E1001 and set this to that value
// plus a small margin. The [epd] log line in yat_sched.cpp prints the measured
// milliseconds of every refresh, so the number is one flash and one wake away.
#if defined(YAT_MODEL_E1001)
static constexpr uint32_t PANEL_REFRESH_S = 35;  // placeholder: E1002's number, deliberately
#else
static constexpr uint32_t PANEL_REFRESH_S = 35;  // measured (~30 s) + margin
#endif

// ---------------- pins (reTerminal E1001/E1002 carrier board) ----------------
